import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 3 An unknown goddess","description":"学习 过去完成时的时间参照，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 3 An unknown goddess","description":"学习 过去完成时的时间参照，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 过去完成时的时间参照，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 2 Thirteen equals one","link":"/life/english/new-concept/book-3/unit-01/lesson-002"},"next":{"text":"第三册：培养技能 · Lesson 4 The double life of Alfred Bloggs","link":"/life/english/new-concept/book-3/unit-01/lesson-004"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 2 Thirteen equals one","link":"/life/english/new-concept/book-3/unit-01/lesson-002"},"next":{"text":"第三册：培养技能 · Lesson 4 The double life of Alfred Bloggs","link":"/life/english/new-concept/book-3/unit-01/lesson-004"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-003.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-003.md"}'),i={name:"life/english/new-concept/book-3/unit-01/lesson-003.md"};function l(r,e,s,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-3-an-unknown-goddess" tabindex="-1">第三册：培养技能 · Lesson 3 An unknown goddess <a class="header-anchor" href="#第三册-培养技能-·-lesson-3-an-unknown-goddess" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 3 An unknown goddess&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以古代遗物的发现、记录和解释为主题，训练把事件放进可理解的时间顺序。学习区分考古人员发现的时间与遗物原先形成的时间，同时避免把推断年代说成绝对事实。完成后能够用过去完成时说明一次发现之前已经发生的动作。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>artefact</td><td>/ˈɑːtɪfækt/</td><td>n.</td><td>人工遗物</td><td>an ancient artefact</td></tr><tr><td>excavate</td><td>/ˈekskəveɪt/</td><td>v.</td><td>发掘</td><td>excavate a site</td></tr><tr><td>fragment</td><td>/ˈfræɡmənt/</td><td>n.</td><td>碎片</td><td>a pottery fragment</td></tr><tr><td>date</td><td>/deɪt/</td><td>v.</td><td>确定年代</td><td>date an object</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>date back to — 追溯到某时期，常用一般现在时</li><li>piece together — 拼合碎片或逐步理清信息</li></ul><h2 id="语法讲解-过去完成时的时间参照" tabindex="-1">语法讲解：过去完成时的时间参照 <a class="header-anchor" href="#语法讲解-过去完成时的时间参照" aria-label="Permalink to &quot;语法讲解：过去完成时的时间参照&quot;">​</a></h2><p>过去完成时由 had 加过去分词构成，表达在另一个过去时间点之前已经发生的动作。它需要明确或可由上下文推知的过去参照点；单纯说明一个很久以前发生的事实，并不自动需要过去完成时。叙事中第一次交代较早事件时可用过去完成时，时间关系清楚后不必句句重复。before 和 after 已能表示先后时，一般过去时有时也自然，选择过去完成时主要是为了突出此前完成或对后续事件的影响。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>By the time the team reached the chamber, water had damaged several paintings.</p></blockquote><p>团队到达墓室时，水已经损坏了几幅画。</p><p>reached 是过去参照点；had damaged 把损坏放在到达之前；by the time 表示到那个时间为止。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Ancient builders had built it in 900 若没有另一个过去参照点，通常写 built 更直接；古老不等于过去完成。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>将示范中的 uncovered、had cracked、now keeps 分别重读，听自己的录音能否仅靠这些词判断时间层次。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Researchers uncovered a painted bowl last month. Soil pressure had cracked its base before they arrived. The museum now keeps the fragments in a protective case.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句介绍一个虚构发现，清楚标出发现前的损坏与现在的保管安排。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>过去时报告发现，过去完成时回溯损坏，现在时描述当前保存状态。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句中先发生的是到达还是损坏？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 损坏。</p><p><strong>解析：</strong> had damaged 位于 reached 之前。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：The team found that someone ___ the box earlier.（had opened/opens）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> had opened</p><p><strong>解析：</strong> earlier 和 found 建立过去之前的关系。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把 date back to 用于单数主语：The temple ___ the tenth century.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> dates back to</p><p><strong>解析：</strong> 主语单数且陈述现存建筑的历史属性。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去完成时的时间参照。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-002">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-004">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
